//! The complete study argument. This is editorial material, not product policy.

use super::super::super::{charts, escape};
use super::super::{Publication, Result, case_html, q, table, value};
use std::path::Path;

pub(super) fn pages(
    p: &Publication,
    public: &Path,
    correction: String,
) -> Result<Vec<(&'static str, String)>> {
    let mut pages = Vec::new();
    pages.push(("Making work land", format!("<p class=\"kicker\">spice / A field guide to a self-hosting appliance</p><h1>Making<br>work land.</h1><p class=\"deck\">A month of work. Several kinds of evidence.<br>No single green light.</p>{}<div class=\"stats\"><div class=\"stat\"><strong>{}</strong><span>selected deliveries · Q01</span></div><div class=\"stat\"><strong>{}</strong><span>eligible phase admissions · Q05</span></div><div class=\"stat\"><strong>{}</strong><span>histories with a finding · Q14</span></div></div><p class=\"cover-note\">{} to {} · UTC · frozen at {}.<br>Completion, correction, proof and continuity—read from one saved population.</p>", charts::intervals::calendar(q(p,"Q17"),public,"delivery-calendar")?, value(p,"Q01","Selected"), q(p,"Q06").denominator, value(p,"Q14","Any recorded finding"), p.first_delivery_day, p.last_delivery_day, p.horizon_day)));

    pages.push(("Population and reading rules", page("Scope / 01", "One cohort. Several denominators.", &format!("<p class=\"lede\">The delivery cohort answers what had completed. Admission populations answer what happened after work entered. They are not interchangeable.</p>{}<div class=\"columns\"><section><h3>Selected delivery</h3><p>The latest 1,500 distinct completed births at the frozen horizon. A reopened task has to complete again. Deletion is not delivery. The independently captured board census agrees with every selected identity and all reconstructed completions.</p></section><section><h3>Admission exposure</h3><p>Phase comparisons use non-review claims admitted in the delivery calendar window, with a common 24-hour follow-up. Task waiting starts at task admission instead. Late observations remain censored, not failures or convenient exclusions.</p></section></div><p>Fixed public categories recognize only explicitly allowlisted whole project labels; other markers use a generic category. Dots imply no hierarchy, and raw project names are not published. These categories group work rather than rank workers.</p><p class=\"limit\">Historical identity and vocabulary may be migration-normalized. This is a replay of the frozen canonical evidence, not a recovered archive of every original envelope. Field-specific rules are in the provenance table.</p><p class=\"evidence\">Q01 · Q03–Q05 · Q09 · Q18 · provenance</p>", charts::bars(q(p,"Q03"),None,public,"delivery-composition")?))));

    pages.push(("Operating map", page("Operating map / 02", "Authority crosses boundaries.", "<p class=\"lede\">The appliance coordinates work, admission and publication. Each boundary answers a different question; no one green light answers them all.</p><div class=\"mechanism\"><div><strong>Task journal</strong>What was admitted, claimed, phased, corrected or closed?</div><div><strong>Proof admission</strong>Which selected tree and declared obligations earned trusted credit?</div><div><strong>Git publication</strong>Which implementation head reached an integrated boundary?</div></div><div class=\"mechanism\"><div><strong>Steering</strong>Was a direction delivered and visibly acknowledged?</div><div><strong>Lane lifecycle</strong>Which stable lane carried which declared provider session?</div><div><strong>Running appliance</strong>Which implementation was actually activated?</div></div><div class=\"finding\"><strong>Keep the verbs literal.</strong> A task can be done in one phase but pending in its workflow. A recorded integration can exist without a separately dated activation observation. A session can survive repeated process starts.</div><div class=\"columns\"><section><h3>Policy / capability</h3><p>The following page locates two concrete integrated changes. Those boundaries partition the observation windows; they do not establish exposure to a running capability.</p></section><section><h3>Coverage / exposure</h3><p>Admission counts, phase mix, right-censoring and lifecycle attribution travel beside the outcomes. A release or lapse is a task-state observation, not a diagnosis of worker quality.</p></section></div><p class=\"limit\">The journal and Git preserve publication evidence. This study does not recover a complete build-identity-to-resident-activation chain. No timeline band is labeled activated.</p><p class=\"evidence\">E03 · E05 · Q05–Q07 · Q21–Q27</p>")));

    pages.push(("Integrated boundaries and exposure", page("Operating map / 03", "Integration is not activation.", &format!("<p class=\"lede\">Two recorded boundaries divide a month. They do not isolate a cause.</p>{}<div class=\"columns\"><section><h3>E05 · blocking policy</h3><p>An implementation fact records integration; a later clean verdict closes the task. Neither establishes runtime activation.</p></section><section><h3>E03 · materialization</h3><p>Preserving unchanged bytes has a narrow recorded experiment. It does not explain the whole admission population.</p></section></div><p class=\"limit\">Pre-policy, policy-to-refill and post-refill abbreviate integration boundaries, not activation regimes. The changing phase mix is visible beside the calendar.</p><p class=\"evidence\">E03 · E05 · Q07 · complete ordered cases</p>", charts::intervals::windows(p,q(p,"Q07"),public,"integration-windows")?))));

    pages.push(("Common-follow-up landing outcomes", page("Landing / 04", "Same follow-up. Different mix.", &format!("<p class=\"lede\">Every eligible admission stays in the 24-hour denominator. Outcomes are first phase boundaries, not eventual workflow deliveries.</p>{}<div class=\"columns\"><section><h3>What changes visibly</h3><p>The post-refill todo window records 450 phase completions among 491 eligible admissions; the policy-to-refill window records 470 among 697. The pre-policy todo window records 488 among 605. These counts describe the admitted work, not a treatment effect.</p></section><section><h3>What keeps it honest</h3><p>The legacy implementation label has only five eligible episodes. Plans and todos are separate. Late admissions are reported as censored; missing-history episodes would remain explicit rather than becoming successes.</p></section></div><p class=\"limit\">Completion, release, lapse, deletion and derived different-lane transfer are distinct first outcomes. Same-lane carries and rebounds preserve the claim episode. Overlapping operational changes, changing task mix and migration-normalized provenance rule out a causal speedup claim.</p><p class=\"evidence\">Q05–Q07 · eligibility, ordered outcome counts and exposure tables</p>", charts::outcomes(p,public,"phase-outcomes")?))));

    pages.push(("Waiting and held time", page("Landing / 05", "Queue time is not held time.", &format!("<p class=\"lede\">Separate clocks. Separate conditional populations.</p>{}{}<p class=\"limit\">Waiting: admission → first claim inside 24h; 29 no-first-claim and 81 late observations remain in Q09. Held: canonical claim → first boundary, not labor or CPU. Quantiles use the higher empirical order statistic without interpolation; small legacy groups are not trend estimates.</p><p class=\"evidence\">Q08–Q10 · complete quantiles, definitions and censoring</p>", charts::intervals::quantiles(q(p,"Q08"),public,"waiting-clock")?, charts::intervals::quantiles(q(p,"Q10"),public,"held-clock")?))));

    pages.push(("Incomplete work and inter-claim gaps", page("Landing / 06", "The unfinished denominator matters.", &format!("<p class=\"lede\">Admission puts unfinished work back in view.</p>{}{}<p>{} admissions were deleted before a first claim; {} after one; {} remain incomplete. Inter-claim gaps condition on a known predecessor boundary and eligible later admission. Unknown predecessors are not zero-duration gaps.</p><p class=\"limit\">Q18 is the non-friction admission population, not the 1,500-delivery cohort. Delivered fixes do not establish that every operational problem was resolved.</p><p class=\"evidence\">Q11 · Q18 · complete support, including non-selected work</p>", charts::bars(q(p,"Q18"),None,public,"admission-disposition")?, charts::intervals::quantiles(q(p,"Q11"),public,"inter-claim-gaps")?, value(p,"Q18","Deleted before first claim"), value(p,"Q18","Deleted after a recorded claim"), value(p,"Q18","Incomplete at horizon")))));

    pages.push(("First verdict and eventual closure", page("Correction circuit / 07", "Final clean is not first-pass clean.", &format!("<p class=\"lede\">The first verdict is assigned at its own boundary. Later clean closure does not rewrite it.</p>{}<div class=\"stats\"><div class=\"stat\"><strong>{}</strong><span>selected deliveries with verdicts · Q13</span></div><div class=\"stat\"><strong>{}</strong><span>ever had a finding · Q14</span></div><div class=\"stat\"><strong>{}</strong><span>no recorded verdict · Q12</span></div></div><p>First findings appear in every observation window. First-clean and first-finding histories remain separate even where the final selected route is clean review.</p><p class=\"limit\">This cohort conditions on completion at the horizon. It is not future review success for all admissions. Historical terminal findings remain their own route; the legacy review-phase-done case has no verdict.</p><p class=\"evidence\">Q02 · Q12–Q14 · E02</p>", charts::sequences::reviews(q(p,"Q12"),public,"first-review-verdict")?, q(p,"Q13").denominator, value(p,"Q14","Any recorded finding"), value(p,"Q12","No recorded review verdict")))));

    pages.push(("Rounds, corrections and attribution", page("Correction circuit / 08", "Order survives the final head.", &format!("<p class=\"lede\">Repeated verdicts and correction births remain visible.</p>{}{}<p class=\"limit\">Verdicts join the preceding non-review phase author, not the creator: {} same-lane, {} different-lane. This does not prove independent judgment. Recorded correction flows are results, not request operands; only E01 separately proves its implementation-only request.</p><p class=\"evidence\">Q13 · Q15–Q16 · ordered correction support</p>", charts::sequences::review_braid(p,public,"ordered-review-rounds")?, charts::sequences::flows(q(p,"Q16"),public,"correction-flows")?, value(p,"Q15","Same lane"), value(p,"Q15","Different lane")))));

    pages.push(("Ordered correction case", correction));

    pages.push(("Historical closure inventory", page("Correction circuit / 10", "Preserve the route that happened.", &format!("<p class=\"lede\">Modern clean-only intuition is not a historical replay rule.</p>{}{}<p>A done fact closes the current phase. Whether it ends the workflow depends on the recorded flow and later state transitions. A terminal historical finding can count as completion without being relabeled clean; later reopening invalidates that completed episode.</p><p class=\"limit\">Operator closure is an explicit route with zero selected occurrences here. Zero is reported, not dropped. The legacy review-phase-done case remains distinct from ordinary no-review completion.</p><p class=\"evidence\">E02 · Q02 · selected task support and historical reconstruction receipt</p>", table(q(p,"Q02"),None), case_html(case(p,"E02")?)))));

    pages.push(("Recorded materialization experiment", page("Proof / 11", "Avoid rewriting unchanged bytes.", &format!("<p class=\"lede\">A narrow mechanism claim, not a fleet performance score.</p>{}{}<div class=\"columns\"><section><h3>Recorded conditions</h3><p>Same packages, target directory and machine. Historical observations—not newly run benchmarks.</p></section><section><h3>The mechanism</h3><p>Write changed bytes, remove unselected paths, preserve unchanged files and their timestamps.</p></section></div><p class=\"limit\">Preserving times while changing absolute workspace location was not the expensive arm. These three observations do not generalize to every task, era or machine.</p><p class=\"evidence\">E03 · Q19–Q20 · exact commit body retained privately</p>", charts::bars(q(p,"Q19"),None,public,"recorded-materialization-seconds")?, charts::bars(q(p,"Q20"),None,public,"recorded-materialization-crates")?))));

    pages.push(("Proof credit and bounded validation", page("Proof / 12", "Reuse credit. Keep the obligation.", &format!("<p class=\"lede\">A receipt belongs to a selected identity and declared obligations, not a worker's memory of a green run.</p>{}<div class=\"columns\"><section><h3>Separate resource bounds</h3><p>Coarse shard admission, compiler jobs and test workers are different dimensions. Bounding one does not establish a bound on the whole process family.</p></section><section><h3>Integrity stays required</h3><p>Refill holds possession while the run measures the tree, seals its selected identity and verifies object identity. Avoided copies or recompiles do not waive those checks.</p></section></div><div class=\"finding\"><strong>Seven retained seal facts · Q30.</strong> There is no complete historical denominator for receipt reuse, validation commands or proof cost. Missing or GC-censored records are not zero cost.</div><p class=\"limit\">Mechanism evidence is not measured CPU utilization. Combining this experiment with admission outcomes would not establish a causal fleet speedup.</p><p class=\"evidence\">E03 · Q19–Q20 · Q30 · pinned source</p>", charts::sequences::proof(public,"proof-boundary")?))));

    pages.push(("Continuity identities", page("Continuity / 13", "A lane is not a process start.", &format!("<p class=\"lede\">Stable lanes, declared provider sessions, occupants and lifecycle events have different grains.</p>{}<div class=\"mechanism\"><div><strong>Lane · L</strong>Stable coordination identity across claim renewal and process lifecycle.</div><div><strong>Session · S</strong>Recorded lane/vendor/provider-session identity tuple; not every declaration.</div><div><strong>Configuration · C</strong>Observed declaration or retune, not today's setting projected backward.</div></div><div class=\"columns\"><section><h3>Declarations repeat</h3><p>The same provider-session identity can be declared again and participate in several process starts or compactions. Those events are not new workers.</p></section><section><h3>Occupants can change</h3><p>Same-lane carries and rebounds preserve a claim episode while updating the occupant. An occupant-only lapse is joined to its recorded claimant, not guessed from the current lane.</p></section></div><p class=\"limit\">Session span endpoints are first and last retained observations. They are not proved activation or termination times. Configuration aliases distinguish observations without implying equivalent models or providing a model leaderboard.</p><p class=\"evidence\">Q21–Q23 · complete session and configuration alternatives</p>", table(q(p,"Q21"),None)))));

    pages.push(("Observed provider-session spans", page("Continuity / observed spans", "The lane outlives the start.", &format!("<p class=\"lede\">Repeated declarations and process starts are events—not new workers.</p>{}<p class=\"limit\">Spans use first and last retained, day-coarsened observations. They are not proved activation or termination times, and do not establish activity throughout the intervening days. Literal lane order is not a ranking.</p><p class=\"evidence\">Q21–Q23 · all provider-session alternatives</p>", charts::intervals::sessions(p,public,"session-spans")?))));
    pages.push(("Continuity and operational handoff", page("Continuity / 14", "Exposure does not rank workers.", &format!("<p class=\"lede\">Held wall time is exposure—not attention, skill or compute.</p>{}<p>{} compactions, {} retunes and {} unattributed events remain distinct lifecycle observations. E04 was filed by L038, then implemented and reviewed by L036: a cross-lane handoff, not independent review.</p><p class=\"limit\">Starts and exits are event counts, not sessions. Missing attribution stays missing. Six incomplete admissions remain; this delivered fix does not establish that every operational issue was resolved.</p><p class=\"evidence\">E04 · Q18 · Q21–Q24 · every lane and session</p>", charts::continuity(p,public,"lane-exposure")?, value(p,"Q22","lane::compacted"), value(p,"Q23","Observed in-window retunes"), value(p,"Q23","Unattributed lifecycle events")))));

    pages.push(("Campaign origin tree", page("Campaign / origin", "One seed. More than one hand.", &format!("<p class=\"lede\">The origin tree records how work begets work. Authorship is a separate label.</p>{}<p class=\"limit\">This bounded campaign is context, not a replacement cohort. Its origins are independent horizon statements; historical revisions cannot be recovered from edited envelopes alone.</p><p class=\"evidence\">Q28–Q29 · displayed origin edges and frontier</p>", charts::topology::origins(p,public,"campaign-origins")?))));
    pages.push(("Bounded campaign layers", page("Campaign / 15", "Three relations. One node set.", &format!("<p class=\"lede\">Origins, blocking dependencies and corrections have different shapes because they mean different things.</p>{}<p class=\"scope\">{} displayed nodes; {} omitted public campaign nodes. Empty cells mean no displayed relation, not no outside dependency.</p><p class=\"limit\">Origin and dependency statements come from the independent horizon board; correction requests and phase authors come from ordered journal observations. Publication-inadmissible context is not expanded into a hidden graph.</p><p class=\"evidence\">Q28–Q29 · complete nodes, typed edges and frontier</p>", charts::topology::campaign(p,public,"campaign-layers")?, p.campaign.nodes.len(), p.campaign.omitted_public_nodes))));

    pages.push(("Git concordance", page("Landing boundary / 16", "The fact head comes first.", &format!("<p class=\"lede\">Exact merge parents carry the join. Trailers do not replace it.</p>{}<div class=\"stats\"><div class=\"stat\"><strong>{}</strong><span>integrated phase boundaries · Q25</span></div><div class=\"stat\"><strong>{}</strong><span>available referenced objects · Q26</span></div><div class=\"stat\"><strong>{}</strong><span>matching head trailers · Q27</span></div></div><p>Of 1,984 non-review phase heads, 582 have disagreeing retained task trailers and 1,360 have no unambiguous trailer. They are not reassigned from a later review head.</p><p class=\"limit\">No separately dated done-to-integration interval is recorded. Object topology does not date runtime activation or migration execution, or establish exclusive code ownership.</p><p class=\"evidence\">Q25–Q27 · curated Git alternatives</p>", charts::topology::git(p,public,"git-joins")?, value(p,"Q25","Recorded integrated boundary"),value(p,"Q26","Available commits"),value(p,"Q27","Matching retained task trailer")))));

    pages.push(("Evidence strength and provenance", page("Limits / 17", "Normalized is not untouched.", "<p class=\"lede\">The saved evidence is reproducible. Its older rows are not universally original event-time bytes.</p><div class=\"table-wrap\"><table><caption>How to read the evidence classes</caption><thead><tr><th scope=\"col\">Class</th><th scope=\"col\">Supports</th><th scope=\"col\">Does not support</th></tr></thead><tbody><tr><th scope=\"row\">Frozen typed facts</th><td>Canonical order, retained event fields, historical state transitions</td><td>A claim that all retained spellings predate every migration</td></tr><tr><th scope=\"row\">Independent horizon census</th><td>Distinct cohort reconciliation and horizon statements</td><td>Unrecorded intermediate statement revisions</td></tr><tr><th scope=\"row\">Retained command record</th><td>Explicit correction operand in E01</td><td>A complete uncensored request ledger</td></tr><tr><th scope=\"row\">Exact Git objects</th><td>Recorded publication joins, parent topology and curated source record</td><td>Runtime activation, migration execution time or exclusive ownership</td></tr><tr><th scope=\"row\">Report-derived quantities</th><td>Named populations, denominators, ordered reductions and aggregate distributions</td><td>Causal improvement, CPU utilization or worker/model superiority</td></tr></tbody></table></div><div class=\"columns\"><section><h3>Known applicability</h3><p>Task identities contract from historical handles; vocabulary is normalized; claim-time allocation and creation context can be reconstructed by migrations. Field-specific source modules and schema steps are in the complete provenance table.</p></section><section><h3>Known absence</h3><p>There is no general per-row migration execution audit or pre-migration envelope archive. Source integration dates do not establish which day a migration ran against a particular row.</p></section></div><p class=\"limit\">Decoder/schema generation, frozen bytes, consumer and rule digests are pinned privately. Later-schema re-export is not assumed equivalent. Missing, censored and potentially reconstructed evidence remain named limitations, not repaired history.</p><p class=\"evidence\">provenance · cohort reconciliation · private snapshot manifest</p>")));

    pages.push(("Offline bundle and reproduction", page("Publication / 18", "Share the guide. Keep the originals separate.", "<p class=\"lede\">The offline reader receives the entire sanitized argument and its support—not credentials or promises of restricted source access.</p><div class=\"bundle\"><h3>Publication bundle</h3><ul><li>index.html — semantic narrative, local fonts and vector figures</li><li>making-work-land.pdf — selectable portrait print edition</li><li>tables.html — every quantity, graph alternative, lane/session strip and task support row</li><li>data.json, measurements.csv, tasks.csv — the same allowlisted analytical records</li><li>assets/ — deterministic SVGs, unmodified licensed fonts and license texts</li><li>manifest.json — content digests and the observed local print boundary</li></ul></div><div class=\"columns\"><section><h3>Private evidence</h3><p>Exact identities, source positions, precise instants, the command operand record, Git objects and provenance maps remain outside the publication tree. The saved one-off consumer belongs there too, not in the product's editorial API.</p></section><section><h3>Reproduction boundary</h3><p>Reacquisition uses the admitted native fixed-horizon reader, with bounded pages and a decoder/schema/residency pin. Rendering reuses the saved snapshot through one pinned local Chromium boundary. Re-export is not a substitute for the saved normalized bytes.</p></section></div><p class=\"limit\">Overview instants are day-coarsened; curated cases use hours. Minute-scale durations are aggregate distributions. Precise seconds belong only to the attributed recorded experiment. No raw task, lane, session, Git or machine identity is part of the shareable bundle.</p><p class=\"evidence\">Public manifest · complete support · separate private reproduction record</p>")));

    pages.push(("What this study establishes", page("Reading the result / 19", "Landing needs several kinds of evidence.", &format!("<p class=\"lede\">The result is not one efficiency score. It is a set of observable boundaries that must not be collapsed.</p><ol class=\"steps\"><li><strong>Completion has a historical route.</strong> {} selected deliveries close through clean review; {} close through a historically terminal finding. Ordinary flow-ending done and legacy review-phase done remain distinct. Q02.</li><li><strong>Corrections survive clean closure.</strong> {} selected reviewed deliveries have at least one finding. First verdicts, correction flows and ordered rounds retain that history. Q12–Q16.</li><li><strong>Comparisons need exposure.</strong> {} eligible phase admissions share 24-hour follow-up; {} late admissions remain censored. Phase composition and conditional waiting distributions prevent a casual before/after efficiency claim. Q05–Q10.</li><li><strong>A mechanism can stand on narrow evidence.</strong> The recorded unchanged refill avoided recompilation without weakening sealing or verification. The three historical arms do not prove a fleet speedup. E03, Q19–Q20.</li><li><strong>Continuity has several identities.</strong> Stable lanes, provider-session spans and occupants cannot be counted as interchangeable workers. Filing, phase authorship and review are separate. E04, Q21–Q24.</li></ol><div class=\"finding\"><strong>The useful conclusion:</strong> treat delivery, proof admission, integration and operational continuity as separate evidence-bearing transitions. A final label alone is too small a record.</div><p class=\"limit\">No activation chain, causal speedup, model ranking, exclusive code ownership or independent-review guarantee is inferred. The complete offline tables preserve the quantities even where the observation is no improvement or incomplete work.</p><p class=\"evidence\">Q01–Q30 · E01–E05 · complete sanitized support</p>", value(p,"Q02","clean review"), value(p,"Q02","historically terminal finding"), value(p,"Q14","Any recorded finding"), q(p,"Q06").denominator, value(p,"Q05","Late, right-censored")))));
    pages.insert(1, ("Visual index", atlas()));
    Ok(pages)
}

fn page(kicker: &str, title: &str, body: &str) -> String {
    format!(
        "<p class=\"kicker\">{}</p><h2>{}</h2>{body}",
        escape(kicker),
        escape(title)
    )
}

fn case<'a>(publication: &'a Publication, id: &str) -> Result<&'a super::super::Case> {
    publication
        .cases
        .iter()
        .find(|case| case.id == id)
        .ok_or_else(|| format!("curated case missing: {id}").into())
}

fn atlas() -> String {
    let mut html = String::from(
        "<p class=\"kicker\">Contact sheet / One visual grammar</p><h2>The argument, at a glance.</h2><p class=\"atlas-deck\">Colour follows the diagram family. Numbers follow the reading order.<br>Every picture links to a full figure; every figure links to its evidence.</p><div class=\"atlas\">",
    );
    for (index, (name, title, family)) in charts::ATLAS.iter().enumerate() {
        html.push_str(&format!("<a class=\"atlas-card family-{}\" href=\"#fig-{name}\"><img src=\"assets/{name}.svg\" alt=\"Figure {:02}: {}\"/><span><b>{:02} · {family}</b><strong>{}</strong></span></a>",family.to_lowercase(),index+1,escape(title),index+1,escape(title)));
    }
    html.push_str("</div><p class=\"scope\">Magnitude: length. Flow: share. Structure: order or mechanism.<br>Time: calendar or observed span. Topology: exact typed relationships.</p>");
    html
}
